import { test, expect } from '@playwright/test';

test.describe('File Upload and Download', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/upload');
  });

  test('should upload a file successfully', async ({ page }) => {
    const filePath = 'path/to/your/file.txt';
    await page.getByLabel('Upload File').setInputFiles(filePath);
    await page.getByRole('button', { name: 'Upload' }).click();
    await expect(page.getByText('File uploaded successfully')).toBeVisible();
  });

  test('should download the previously uploaded file', async ({ page }) => {
    await page.goto('/downloads');
    await page.getByRole('link', { name: 'Download file.txt' }).click();
    const [download] = await Promise.all([
      page.waitForEvent('download'),
      page.getByRole('link', { name: 'Download file.txt' }).click(),
    ]);
    const path = await download.path();
    expect(path).toBeTruthy();
  });
});
